{"content": "# -*- coding: utf-8 -*-
"""
固定燃烧源排放清单编制 — 火电热力(POWER)目标 通用工具调用型Agent执行脚本
方法依据: T/CSES 144-2024《城市大气污染源排放清单编制技术指南》
  - 分类: §5.2.1 / §7.1 电力热力源 = D4411 火力发电, D4412 热电联产, D4417 生物质能发电, D4430 热力生产和供应
           §8.1 工业源 = B06-12 采矿业, C13-43 制造业, D45 燃气生产和供应业 (化石燃料固定燃烧=工业锅炉 §8.3)
  - 核算: §7.2 产排污系数法 公式(2) E=A*EF*(1-η); 燃煤SO2 公式(3), 颗粒物 公式(4)-(6)
  - 系数: 附录D 表D.1; 附录C 表C.1-C.3; 控制效率 附录A 表A.1
"""
import json
import math
import os
import sys
import traceback

import pandas as pd
import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
RUN_PKG = os.path.dirname(HERE)
sys.path.insert(0, os.path.join(HERE, 'work'))
from factor_tables import (D1, A1, AR, FPM, FBC_OC, SR, POLLUTANTS,
                           nox_by_capacity, GAS_FUELS)

PKG = RUN_PKG
INPUTS = os.path.join(PKG, 'inputs')
OUTPUTS = os.path.join(PKG, 'outputs')
os.makedirs(OUTPUTS, exist_ok=True)

POWER_INDS = {'4411', '4412', '4417', '4430'}
INDUSTRIAL_FIRST2 = list(range(6, 13)) + list(range(13, 44)) + [45]

ALL_POLLUTANTS = ['SO2', 'NOx', 'CO', 'VOC', 'PM2.5', 'PM10', 'BC', 'OC', 'NH3']

POWER_DEV_COLS = ['电站锅炉/燃气轮机编号', '电站锅炉/燃气轮机类型代码', '电站锅炉/燃气轮机类型']
IND_DEV_COLS = ['工业锅炉编号', '工业锅炉类型代码', '工业锅炉类型']

FUEL_SLOTS = [
    dict(n='一', type='燃料一类型', amount='燃料一消耗量', unit='燃料一消耗量单位',
         lhv='燃料一低位发热量（千卡/千克或千卡/标准立方米）',
         sulfur='燃料一平均收到基含硫量', sulfur_unit='燃料一平均收到基含硫量单位',
         ash='燃料一平均收到基灰分（%）', vm='燃料一平均干燥无灰基挥发分（%）',
         carbon='燃料一单位热值含碳量（吨碳/太焦）', oxi='燃料一碳氧化率（%）',
         gen='其中：发电消耗量', heat='其中：供热消耗量'),
    dict(n='二', type='燃料二类型', amount='燃料二消耗量', unit='燃料二消耗量单位',
         lhv='燃料二低位发热量（千卡/千克或千卡/标准立方米）',
         sulfur='燃料二平均收到基含硫量', sulfur_unit='燃料二平均收到基含硫量单位',
         ash='燃料二平均收到基灰分（%）', vm='燃料二平均干燥无灰基挥发分（%）',
         carbon='燃料二单位热值含碳量（吨碳/太焦）', oxi='燃料二碳氧化率（%）',
         gen='其中：发电消耗量.1', heat='其中：供热消耗量.1'),
]

# ------------------------------------------------------------------ load
def load_inputs():
    df = pd.read_excel(os.path.join(INPUTS, '基102-2002_原始结构脱敏输入.xlsx'), sheet_name='Sheet1', header=0)
    ctl = pd.read_excel(os.path.join(INPUTS, '基101-2002_原始结构脱敏输入.xlsx'), sheet_name='Sheet1', header=0)
    idx = json.load(open(os.path.join(INPUTS, 'source_identity_index.json'), encoding='utf-8'))
    manifest = json.load(open(os.path.join(PKG, 'run_manifest.json'), encoding='utf-8'))
    # source_id by excel row (source_row is 1-based incl header; pandas index = source_row - 2)
    sid_by_row = {}
    for r in idx['records']:
        sid_by_row[r['source_row']] = r['source_id']
    df['_excel_row'] = np.arange(2, len(df) + 2)
    df['source_id'] = df['_excel_row'].map(sid_by_row)
    assert df['source_id'].notna().all(), 'identity index does not cover all rows'
    ctl_by_credit = {}
    for _, row in ctl.iterrows():
        cred = row['统一社会信用代码']
        if pd.isna(cred):
            continue
        ctl_by_credit.setdefault(str(cred).strip(), []).append(row)
    return df, ctl_by_credit, manifest, idx


# ------------------------------------------------------------------ classification
def in_industrial_scope(ind_code):
    if not ind_code or ind_code == 'nan':
        return False
    try:
        first2 = int(ind_code[:2])
    except Exception:
        return False
    return first2 in INDUSTRIAL_FIRST2


def classify_row(row):
    ind = str(row['行业类别代码']).strip()
    has_power = any(not pd.isna(row[c]) for c in POWER_DEV_COLS)
    has_ind = any(not pd.isna(row[c]) for c in IND_DEV_COLS)
    if ind in POWER_INDS:
        return 'POWER', 'INDUSTRY_D44_POWER_SCOPE', f'行业类别代码{ind}属于指南§7.1电力热力源范围'
    if has_ind:
        if in_industrial_scope(ind):
            return 'INDUSTRIAL_BOILER', 'INDUSTRY_INDUSTRIAL_SCOPE', '工业锅炉且行业属于指南§8.1工业源范围(采矿业/制造业/燃气生产和供应业)'
        return 'OUT_OF_SCOPE', 'IND_BOILER_NON_INDUSTRIAL_INDUSTRY', f'工业锅炉但行业类别代码{ind}不属于工业源范围'
    if has_power:
        if ind == '4419':
            return 'OUT_OF_SCOPE', 'WASTE_INCINERATION_D4419', '电站锅炉/燃气轮机但行业为4419其他电力生产(垃圾焚烧发电), 指南§13归入废弃物处理源, 不在电力热力源(§7.1)与工业锅炉(§8.3)范围'
        return 'OUT_OF_SCOPE', 'POWER_DEVICE_NON_POWER_INDUSTRY', f'电站锅炉/燃气轮机但行业类别代码{ind}不属于指南§7.1电力热力源范围(自备电厂), 亦非§8.3工业锅炉'
    return 'OUT_OF_SCOPE', 'NO_DEVICE_INFO', '基102行未填写电站锅炉/燃气轮机或工业锅炉设备信息'


# ------------------------------------------------------------------ fuel mapping
FUEL_TO_D1 = {
    '原煤': '煤炭', '一般烟煤': '煤炭', '无烟煤': '煤炭', '褐煤': '煤炭', '煤制品': '煤炭',
    '煤矸石（用于燃料）': '煤矸石', '焦炉煤气': '焦炉煤气', '高炉煤气': '高炉煤气',
    '发生炉煤气': '其它煤气', '天然气': '天然气', '液化天然气': '液化天然气',
    '液化石油气': '液化石油气', '炼厂干气': '炼厂干气', '柴油': '柴油', '燃料油': '燃料油',
    '原油': '原油', '石油焦': '石油焦', '其他石油制品': '其它石油制品',
}
NO_FACTOR_FUELS = {'生物燃料', '城市生活垃圾（用于燃料）', '工业废料（用于燃料）', '其他燃料'}
OIL_FUELS = {'柴油', '燃料油', '原油', '汽油', '煤油', '其它液体燃料', '石油焦', '其它石油制品',
             '液化天然气', '液化石油气'}

COAL_TECH_MAP = {
    '煤粉炉': '煤粉炉', '循环流化床锅炉': '流化床炉', '链条炉': '自动炉排层燃炉',
    '层燃炉': '自动炉排层燃炉', '其他层燃炉': '自动炉排层燃炉',
}


def resolve_tech(row, d1_fuel):
    """返回 D.1 第三级燃烧技术名称 (None = 无法确定)."""
    if d1_fuel in GAS_FUELS:
        return '燃气锅炉'
    if d1_fuel in OIL_FUELS:
        return '燃油锅炉'
    # coal family -> need 燃烧方式
    has_power = any(not pd.isna(row[c]) for c in POWER_DEV_COLS)
    if has_power:
        src = row['电站锅炉燃烧方式']
    else:
        src = row['工业锅炉燃烧方式']
    if pd.isna(src):
        return None
    s = str(src).strip()
    if s == '室燃炉':
        return '燃气锅炉'
    return COAL_TECH_MAP.get(s)


def is_gas_unit(row):
    """消耗量单位 万立方米 (气体燃料按m3)."""
    return True  # per-component handling instead


# ------------------------------------------------------------------ controls
def a1_poll_keys():
    return ['SO2', 'NOx', 'VOC', 'PM2_5', 'PM10c', 'BC', 'OC']


def map_process_to_a1(proc, cat):
    """map 处理工艺名称 -> list of A1 row names (series combination)."""
    if proc is None or proc == '' or proc == 'nan':
        return []
    p = proc
    # --- desulfurization
    if '双碱' in p:
        return ['双碱法']
    if '石灰石/石膏' in p or '石灰/石膏' in p:
        return ['石灰石/石膏法']
    if '氨法' in p:
        return ['氨法']
    if '氧化镁' in p:
        return ['氧化镁法']
    if '海水' in p:
        return ['海水法']
    if '烟气循环流化床' in p:
        return ['烟气循环流化床法']
    if '旋转喷雾干燥' in p or '半干法' in p:
        return ['旋转喷雾干燥法']
    if '炉内喷钙' in p or '炉内脱硫' in p:
        return ['炉内喷钙法']
    if '钠碱' in p or '碱液' in p or '碱法' in p:
        return ['其他脱硫技术']
    # --- denitration (combined first)
    if '低氮' in p and 'SNCR' in p and 'SCR' in p:
        return ['低氮燃烧技术', '选择性非催化还原法', '选择性催化还原法']
    if '低氮' in p and 'SCR' in p:
        return ['低氮燃烧技术+选择性催化还原法']
    if '低氮' in p and 'SNCR' in p:
        return ['低氮燃烧技术+选择性非催化还原法']
    if 'SNCR' in p and 'SCR' in p:
        return ['选择性非催化还原法', '选择性催化还原法']
    if 'SCR' in p or '选择性催化还原' in p:
        return ['选择性催化还原法']
    if 'SNCR' in p or '选择性非催化还原' in p:
        return ['选择性非催化还原法']
    if '低氮' in p:
        return ['低氮燃烧技术']
    # --- dust (specific first)
    if '电袋' in p:
        return ['电袋复合除尘法']
    if '袋' in p:
        return (['多管旋风除尘法', '袋式除尘法'] if '旋风' in p else ['袋式除尘法'])
    if '高效静电' in p:
        return ['高效静电除尘法']
    if '湿式电除尘' in p:
        return ['高效静电除尘法']
    if '静电' in p:
        return ['普通静电除尘法']
    if '旋风' in p:
        return ['多管旋风除尘法']
    if '文丘里' in p:
        return ['湿式除尘法']
    if '重力' in p:
        return ['重力沉降法']
    if '惯性' in p:
        return ['惯性除尘法']
    if any(k in p for k in ['水膜', '喷淋', '水浴', '湿式喷雾', '湿法除尘', '板式', '管式', '湿法', '湿式']):
        return ['湿式除尘法']
    if '机械' in p:
        return ['机械式除尘法']
    if '过滤' in p:
        return ['袋式除尘法']
    if '无组织' in p:
        return ['无组织尘高效控制技术'] if '高效' in p else ['无组织尘一般控制技术']
    if '脱硫' in p:
        return ['其他脱硫技术']
    if '除尘' in p:
        return ['其他除尘技术']
    # --- VOCs
    if '活性炭' in p or '吸附' in p:
        return ['活性炭法']
    if '沸石' in p:
        return ['沸石转轮吸附法']
    if '蓄热式' in p:
        return ['蓄热式热力燃烧法']
    if '光解' in p:
        return ['光解']
    if '光催化' in p:
        return ['光催化']
    if '冷凝' in p:
        return ['冷凝法']
    if '催化燃烧' in p:
        return ['催化燃烧法']
    if '低温等离子体' in p:
        return ['低温等离子体']
    if '生物过滤' in p:
        return ['生物过滤法']
    if '热力燃烧' in p:
        return ['热力燃烧']
    return []


def series_combine(vals_pct):
    """vals_pct: list of efficiencies in %; returns combined % (1-prod(1-e/100))."""
    rem = 1.0
    for v in vals_pct:
        rem *= (1.0 - v / 100.0)
    return (1.0 - rem) * 100.0


def _group_poll_of(a1_rows):
    """primary pollutant group of mapped A1 rows."""
    has_pm = any(A1[n]['PM2_5'] > 0 for n in a1_rows)
    has_so2 = any(A1[n]['SO2'] > 0 for n in a1_rows)
    has_nox = any(A1[n]['NOx'] > 0 for n in a1_rows)
    has_voc = any(A1[n]['VOC'] > 0 for n in a1_rows)
    if has_pm:
        return 'PM'
    if has_so2:
        return 'SO2'
    if has_nox:
        return 'NOx'
    if has_voc:
        return 'VOC'
    return None


def build_controls(row, ctl_by_credit):
    """Return (eta_per_pollutant dict in %, method_names list, ctl_flag, low_nox_used).
    eta keys: SO2, NOx, VOC, PM2_5, PM10c, BC, OC
    """
    cred = str(row['统一社会信用代码']).strip()
    facs = ctl_by_credit.get(cred, [])
    # per-measure A1 rows
    measures = []  # list of (name, A1 dict)
    low_nox_in_ctl = False
    for f in facs:
        cat = str(f['废气治理设施名称']) if not pd.isna(f['废气治理设施名称']) else ''
        proc_raw = f['处理工艺名称']
        proc = str(proc_raw).strip() if not pd.isna(proc_raw) else ''
        a1_names = map_process_to_a1(proc, cat)
        if not a1_names:
            continue
        reported = f['去除效率（%）']
        reported = None if (pd.isna(reported) or not (0 < float(reported) <= 100)) else float(reported)
        for nm in a1_names:
            if '低氮' in nm:
                low_nox_in_ctl = True
        group = _group_poll_of(a1_names)
        # base dict = series of mapped rows
        base = {k: series_combine([A1[nm][k] for nm in a1_names]) for k in a1_poll_keys()}
        if reported is not None and group == 'PM':
            for k in ['PM2_5', 'PM10c', 'BC', 'OC']:
                base[k] = reported
        elif reported is not None and group == 'SO2':
            base['SO2'] = reported
        elif reported is not None and group == 'NOx':
            base['NOx'] = reported
        elif reported is not None and group == 'VOC':
            base['VOC'] = reported
        measures.append((';'.join(a1_names), base))
    # 低氮燃烧 field on 基102 row
    has_power = any(not pd.isna(row[c]) for c in POWER_DEV_COLS)
    ldn_field = row['是否采用低氮燃烧技术'] if has_power else row['是否采用低氮燃烧技术.1']
    low_nox_used = False
    if not pd.isna(ldn_field) and str(ldn_field).strip() == '是' and not low_nox_in_ctl:
        measures.append(('低氮燃烧技术', dict(A1['低氮燃烧技术'])))
        low_nox_used = True
    eta = {k: 0.0 for k in a1_poll_keys()}
    names = []
    for nm, d in measures:
        names.append(nm)
        for k in eta:
            eta[k] = series_combine([eta[k], d[k]])
    return eta, names, bool(facs), low_nox_used


# ------------------------------------------------------------------ components
def build_components(row):
    """list of component dicts: id, fuel_type, d1_fuel, amount, unit, props{...}"""
    comps = []
    for slot in FUEL_SLOTS:
        ftype = row[slot['type']]
        if pd.isna(ftype):
            continue
        ftype = str(ftype).strip()
        comp = dict(id='F' + slot['n'], fuel_type=ftype,
                    d1_fuel=FUEL_TO_D1.get(ftype),
                    amount=_num(row[slot['amount']]),
                    unit=(str(row[slot['unit']]).strip() if not pd.isna(row[slot['unit']]) else ''),
                    lhv=_num(row[slot['lhv']]),
                    sulfur=_num(row[slot['sulfur']]),
                    sulfur_unit=(str(row[slot['sulfur_unit']]).strip() if not pd.isna(row[slot['sulfur_unit']]) else ''),
                    ash=_num(row[slot['ash']]), vm=_num(row[slot['vm']]),
                    carbon=_num(row[slot['carbon']]), oxi=_num(row[slot['oxi']]),
                    gen=_num(row[slot['gen']]), heat=_num(row[slot['heat']]))
        comps.append(comp)
    oth = _num(row['其他燃料消耗总量（吨标准煤）'])
    if oth is not None and oth > 0:
        comps.append(dict(id='FO', fuel_type='其他燃料(吨标准煤)', d1_fuel=None,
                          amount=oth, unit='吨标准煤', lhv=None, sulfur=None,
                          sulfur_unit='', ash=None, vm=None, carbon=None, oxi=None,
                          gen=None, heat=None))
    return comps


def _num(v):
    if v is None or (isinstance(v, float) and math.isnan(v)):
        return None
    if isinstance(v, str):
        v = v.strip()
        if v == '':
            return None
        try:
            return float(v)
        except Exception:
            return None
    try:
        f = float(v)
        return f
    except Exception:
        return None


# ------------------------------------------------------------------ per-pollutant factor
def pollutant_factor(comp, row, sector):
    """Return (EF value, EF unit, missing_param or None).
    missing_param: name of the missing required input -> info_insufficient.
    """
    d1_fuel = comp['d1_fuel']
    if d1_fuel is None:
        return None, None, 'FUEL_FACTOR_MISSING'
    tech = resolve_tech(row, d1_fuel)
    if tech is None:
        return None, None, 'COMBUSTION_TECH_MISSING'
    key = (d1_fuel, tech)
    try:
        factors = D1[sector][key]
    except KeyError:
        # try 不分技术 rows
        alt = (d1_fuel, '不分技术')
        if alt in D1[sector]:
            factors = D1[sector][alt]
        else:
            return None, None, 'D1_ROW_MISSING'
    is_gas = d1_fuel in GAS_FUELS
    unit = 'g/m3' if is_gas else 'g/kg'
    # dict of pollutant -> EF
    ef = {}
    missing = None
    for p in ['CO', 'NOx', 'SO2', 'VOC', 'PM2.5', 'PM10', 'BC', 'OC']:
        fv = factors[p]
        if p == 'SO2' and fv == 'MB':
            s = comp['sulfur']
            if s is None:
                missing = 'SULFUR_MISSING'
                ef[p] = None
            else:
                ef[p] = 2.0 * (s * 10.0) * (1.0 - SR)  # g/kg; S in %
        elif p in ('PM2.5', 'PM10', 'BC', 'OC') and fv == 'MB':
            ash = comp['ash']
            if ash is None:
                missing = 'ASH_MISSING'
                ef[p] = None
                continue
            sector_c = '电力生产' if sector == '电力生产' else '热力生产和供应'
            ar = AR[(sector_c, tech)]
            fpm25, fpm10 = FPM[(sector_c, tech)]
            fbc, foc = FBC_OC[(sector_c, tech)]
            if p == 'PM2.5':
                ef[p] = 10.0 * ash * (1.0 - ar) * fpm25
            elif p == 'PM10':
                ef[p] = 10.0 * ash * (1.0 - ar) * fpm10
            elif p == 'BC':
                ef_p25 = 10.0 * ash * (1.0 - ar) * fpm25
                ef[p] = ef_p25 * fbc
            else:  # OC
                ef_p25 = 10.0 * ash * (1.0 - ar) * fpm25
                ef[p] = ef_p25 * foc
        elif p == 'NOx' and fv == 'CAP':
            cap = _num(row['对应机组装机容量（万千瓦）'])
            if cap is None:
                missing = 'CAPACITY_MISSING'
                ef[p] = None
            else:
                ef[p] = nox_by_capacity(cap)
        else:
            ef[p] = fv
    return ef, unit, missing


def component_emission(comp, ef, unit):
    """generation 吨 = A * EF. gas: A 万m3 -> m3; solid/liquid: A 吨 -> kg."""
    a = comp['amount']
    if a is None:
        return None, 'ACTIVITY_MISSING'
    if unit == 'g/m3':
        a_conv = a * 1e4  # 万m3 -> m3
    else:
        a_conv = a * 1000.0  # 吨 -> kg
    return a_conv * ef / 1e6, None


# ------------------------------------------------------------------ statuses
def fmt_num(x):
    if x is None:
        return ''
    return format(round(float(x), 6), '.6f').rstrip('0').rstrip('.')


def jdump(x):
    return json.dumps(x, ensure_ascii=False)


def main():
    df, ctl_by_credit, manifest, idx = load_inputs()
    target = manifest['target']  # POWER
    sid_order = list(manifest['candidate_ids'])
    rows_by_sid = {r['source_id']: r for r in idx['records']}

    # ---------------------------------------------------------- classify
    decisions = {}
    for _, r in df.iterrows():
        sid = r['source_id']
        decided, reason, detail = classify_row(r)
        decisions[sid] = dict(source_id=sid, requested_target=target,
                              decided_target=decided, reason_code=reason,
                              reason_detail=detail, row=r)
    # ---------------------------------------------------------- build items
    item_rows = []
    ctl_stats = {'facilities_total': 0, 'facilities_mapped': 0, 'reported_invalid': 0}
    for sid in sid_order:
        r = decisions[sid]['row']
        decided = decisions[sid]['decided_target']
        comps = build_components(r)
        # controls (only meaningful for POWER but compute for all for the record)
        eta, ctl_names, has_ctl, low_nox_used = build_controls(r, ctl_by_credit)
        ctl_stats['facilities_total'] += 1 if has_ctl else 0
        sector = '电力生产' if str(r['行业类别代码']).strip() in ('4411', '4412', '4417') else '热力生产和供应'

        # per-component factor resolution (for POWER)
        comp_factors = []  # list of (comp, ef_dict or None, unit, missing)
        for comp in comps:
            if decided != 'POWER':
                comp_factors.append((comp, None, None, 'NOT_INVOLVED'))
                continue
            ef, unit, missing = pollutant_factor(comp, r, sector)
            comp_factors.append((comp, ef, unit, missing))

        for poll in ALL_POLLUTANTS:
            row_out = dict(source_id=sid, target=decided, pollutant=poll,
                           status='', method='', activity_record_json='',
                           parameter_record_json='', control_record_json='',
                           generation_t='', emission_t='', standard_reference='',
                           reason_code='')
            if decided != 'POWER':
                row_out['status'] = 'not_involved'
                row_out['reason_code'] = 'NOT_REQUESTED_TARGET_POWER_ONLY'
                row_out['method'] = 'not_applicable'
                row_out['activity_record_json'] = jdump(
                    [dict(component_id=c['id'], value=fmt_num(c['amount']), unit=c['unit']) for c in comps])
                row_out['parameter_record_json'] = jdump(
                    _param_records_inputs(comps))
                row_out['control_record_json'] = jdump(
                    [dict(component_id=c['id'], method='', efficiency=0,
                          fine_efficiency=0, coarse_efficiency=0) for c in comps])
                row_out['standard_reference'] = 'T/CSES 144-2024 §7.1 电力热力源范围'
                item_rows.append(row_out)
                continue
            if poll == 'NH3':
                row_out['status'] = 'not_involved'
                row_out['reason_code'] = 'NH3_NOT_COVERED_BY_GUIDELINE'
                row_out['method'] = 'not_applicable'
                row_out['activity_record_json'] = jdump(
                    [dict(component_id=c['id'], value=fmt_num(c['amount']), unit=c['unit']) for c in comps])
                row_out['parameter_record_json'] = jdump(_param_records_inputs(comps))
                row_out['control_record_json'] = jdump(
                    [dict(component_id=c['id'], method=(';'.join(ctl_names) if ctl_names else ''),
                          efficiency=0, fine_efficiency=0, coarse_efficiency=0) for c in comps])
                row_out['standard_reference'] = 'T/CSES 144-2024 §7.2（电力热力源方法未覆盖NH3，附录D表D.1无NH3产生系数）'
                item_rows.append(row_out)
                continue
            # --- POWER, calculable pollutants
            gen_total = 0.0
            emi_total = 0.0
            all_calc = True
            reasons = []
            act_recs = []
            par_recs = []
            ctl_recs = []
            for comp, ef, unit, missing in comp_factors:
                act_recs.append(dict(component_id=comp['id'], value=fmt_num(comp['amount']), unit=comp['unit']))
                ctl_recs.append(dict(component_id=comp['id'],
                                     method=(';'.join(ctl_names) if ctl_names else ''),
                                     efficiency=_eta_for(poll, eta, 'eff'),
                                     fine_efficiency=_eta_for(poll, eta, 'fine'),
                                     coarse_efficiency=_eta_for(poll, eta, 'coarse')))
                if missing is not None or ef is None:
                    all_calc = False
                    reasons.append(f"{comp['id']}:{missing if missing else 'FACTOR_MISSING'}")
                    par_recs.append(dict(component_id=comp['id'],
                                         parameter_id='EF_' + poll,
                                         mode='missing', value='', unit=''))
                    continue
                efp = ef[poll]
                if efp is None:
                    all_calc = False
                    reasons.append(f"{comp['id']}:FACTOR_UNAVAILABLE")
                    par_recs.append(dict(component_id=comp['id'], parameter_id='EF_' + poll,
                                         mode='missing', value='', unit=''))
                    continue
                gen, emissing = component_emission(comp, efp, unit)
                if emissing is not None:
                    all_calc = False
                    reasons.append(f"{comp['id']}:{emissing}")
                    par_recs.append(dict(component_id=comp['id'], parameter_id='EF_' + poll,
                                         mode='missing', value='', unit=''))
                    continue
                if poll == 'PM10':
                    # fine/coarse split
                    ef_fine = ef['PM2.5']
                    ef_coarse = ef['PM10'] - ef['PM2.5']
                    gen_fine, _ = component_emission(comp, ef_fine, unit)
                    gen_coarse, _ = component_emission(comp, ef_coarse, unit)
                    gen = gen_fine + gen_coarse
                    emi = gen_fine * (1 - eta['PM2_5'] / 100.0) + gen_coarse * (1 - eta['PM10c'] / 100.0)
                else:
                    emi = gen * (1 - _eta_pct(poll, eta) / 100.0)
                gen_total += gen
                emi_total += emi
                par_recs.extend(_param_records_poll(comp, poll, efp, unit, ef, row))
            row_out['activity_record_json'] = jdump(act_recs)
            row_out['control_record_json'] = jdump(ctl_recs)
            row_out['parameter_record_json'] = jdump(par_recs)
            row_out['standard_reference'] = _std_ref(poll, comp_factors, row, sector)
            if all_calc and comp_factors:
                row_out['status'] = 'calculated'
                row_out['generation_t'] = fmt_num(gen_total)
                row_out['emission_t'] = fmt_num(emi_total)
                row_out['method'] = _method_name(poll, comp_factors, row, sector)
                row_out['reason_code'] = 'CALCULATED'
            else:
                row_out['status'] = 'information_insufficient'
                row_out['method'] = _method_name(poll, comp_factors, row, sector)
                row_out['reason_code'] = 'INFO_INSUFFICIENT:' + ';'.join(sorted(set(reasons)))
            item_rows.append(row_out)

    # ---------------------------------------------------------- write outputs
    dec_df = pd.DataFrame([dict(source_id=d['source_id'],
                                requested_target=d['requested_target'],
                                decided_target=d['decided_target'],
                                disposition=_disposition(d['decided_target']),
                                reason_code=d['reason_code'],
                                reason_detail=d['reason_detail'])
                           for d in decisions.values()])
    dec_df = dec_df.sort_values('source_id').reset_index(drop=True)
    dec_df.to_csv(os.path.join(OUTPUTS, 'source_decisions.csv'), index=False, encoding='utf-8-sig')

    dis_df = pd.DataFrame([dict(source_id=d['source_id'],
                                target=d['decided_target'],
                                disposition=_disposition(d['decided_target']),
                                reason_code=d['reason_code'])
                           for d in decisions.values()])
    dis_df = dis_df.sort_values('source_id').reset_index(drop=True)
    dis_df.to_csv(os.path.join(OUTPUTS, 'generic_source_disposition.csv'), index=False, encoding='utf-8-sig')

    items_df = pd.DataFrame(item_rows)
    items_df.to_csv(os.path.join(OUTPUTS, 'generic_inventory_items.csv'), index=False, encoding='utf-8-sig')

    exc_df = build_exceptions(decisions, item_rows)
    exc_df.to_csv(os.path.join(OUTPUTS, 'generic_exception_list.csv'), index=False, encoding='utf-8-sig')

    summary = build_summary(manifest, decisions, item_rows, exc_df, ctl_stats)
    with open(os.path.join(OUTPUTS, 'generic_run_summary.json'), 'w', encoding='utf-8') as f:
        json.dump(summary, f, ensure_ascii=False, indent=2)

    print('source_decisions rows:', len(dec_df))
    print('items rows:', len(items_df))
    print('disposition rows:', len(dis_df))
    print('exceptions rows:', len(exc_df))
    print('status counts:')
    print(items_df['status'].value_counts().to_string())
    print('decided target counts:')
    print(dec_df['decided_target'].value_counts().to_string())


def _eta_pct(poll, eta):
    if poll == 'SO2':
        return eta['SO2']
    if poll == 'NOx':
        return eta['NOx']
    if poll in ('PM2.5', 'BC', 'OC'):
        return eta['PM2_5']
    if poll == 'PM10':
        return eta['PM2_5']  # fine fraction; coarse handled separately
    return 0.0


def _eta_for(poll, eta, which):
    if poll == 'PM10':
        if which == 'fine':
            return round(eta['PM2_5'], 4)
        if which == 'coarse':
            return round(eta['PM10c'], 4)
        return round(eta['PM2_5'], 4)
    v = _eta_pct(poll, eta)
    if which in ('fine', 'coarse'):
        return round(v, 4)
    return round(v, 4)


def _disposition(decided):
    if decided == 'POWER':
        return 'included_target'
    if decided == 'INDUSTRIAL_BOILER':
        return 'excluded_other_target'
    return 'excluded_out_of_scope'


def _param_records_inputs(comps):
    recs = []
    for c in comps:
        if c['sulfur'] is not None:
            recs.append(dict(component_id=c['id'], parameter_id='S_ar', mode='input',
                             value=fmt_num(c['sulfur']), unit=c['sulfur_unit'] or '%'))
        if c['ash'] is not None:
            recs.append(dict(component_id=c['id'], parameter_id='A_ar', mode='input',
                             value=fmt_num(c['ash']), unit='%'))
        if c['lhv'] is not None:
            recs.append(dict(component_id=c['id'], parameter_id='LHV', mode='input',
                             value=fmt_num(c['lhv']), unit='千卡/千克或千卡/标准立方米'))
        if c['vm'] is not None:
            recs.append(dict(component_id=c['id'], parameter_id='Vdaf', mode='input',
                             value=fmt_num(c['vm']), unit='%'))
        if c['oxi'] is not None:
            recs.append(dict(component_id=c['id'], parameter_id='carbon_oxidation', mode='input',
                             value=fmt_num(c['oxi']), unit='%'))
    return recs


def _param_records_poll(comp, poll, efp, unit, ef, row):
    recs = []
    if comp['sulfur'] is not None:
        recs.append(dict(component_id=comp['id'], parameter_id='S_ar', mode='input',
                         value=fmt_num(comp['sulfur']), unit=comp['sulfur_unit'] or '%'))
    if comp['ash'] is not None:
        recs.append(dict(component_id=comp['id'], parameter_id='A_ar', mode='input',
                         value=fmt_num(comp['ash']), unit='%'))
    if poll == 'NOx' and ef.get('NOx') is not None and str(row['行业类别代码']).strip() in ('4411', '4412', '4417'):
        cap = _num(row['对应机组装机容量（万千瓦）'])
        if cap is not None:
            recs.append(dict(component_id=comp['id'], parameter_id='installed_capacity', mode='input',
                             value=fmt_num(cap), unit='万千瓦'))
    recs.append(dict(component_id=comp['id'], parameter_id='EF_' + poll, mode='factor',
                     value=fmt_num(efp), unit=unit))
    return recs


def _method_name(poll, comp_factors, row, sector):
    base = 'T/CSES 144-2024 产排污系数法（公式2）'
    coal_mb = any(c['d1_fuel'] in ('煤炭', '煤矸石', '焦炭') for c, _, _, _ in comp_factors)
    if coal_mb and poll in ('SO2', 'PM2.5', 'PM10', 'BC', 'OC'):
        return base + '+物料衡算法（公式3-6）'
    return base


def _std_ref(poll, comp_factors, row, sector):
    d1_sector = '电力生产' if sector == '电力生产' else '热力生产和供应'
    parts = ['T/CSES 144-2024 §7.2.1.2/§7.2.2']
    fuels = sorted(set(c['d1_fuel'] for c, _, _, _ in comp_factors if c['d1_fuel']))
    if fuels:
        parts.append('附录D表D.1(' + d1_sector + '/' + ','.join(fuels) + ')')
    coal = any(c['d1_fuel'] in ('煤炭', '煤矸石', '焦炭') for c, _, _, _ in comp_factors)
    if coal:
        if poll in ('SO2',):
            parts.append('附录C表C.1')
        if poll in ('PM2.5', 'PM10', 'BC', 'OC'):
            parts.append('附录C表C.1/C.2/C.3')
    if poll == 'NH3':
        parts.append('附录D表D.1无NH3产生系数')
    return '；'.join(parts)


def build_exceptions(decisions, item_rows):
    """group by root cause -> one row per group."""
    exc = []
    # counts per root cause across POWER items
    from collections import Counter
    cnt = Counter()
    for it in item_rows:
        rc = it['reason_code']
        if it['status'] == 'information_insufficient':
            cnt[rc.split(':')[1] if ':' in rc else rc] += 1

    def add(eid, sid, poll, cause, action):
        exc.append(dict(exception_id=eid, source_id=sid, pollutant=poll,
                        root_cause=cause, action_required=action))

    power_sids = [sid for sid, d in decisions.items() if d['decided_target'] == 'POWER']
    ind_sids = [sid for sid, d in decisions.items() if d['decided_target'] == 'INDUSTRIAL_BOILER']
    oos_sids = [sid for sid, d in decisions.items() if d['decided_target'] == 'OUT_OF_SCOPE']
    add('EXC-SCOPE-01', power_sids[0] if power_sids else '', 'ALL',
        '电力热力源范围界定（指南§7.1：D4411/D4412/D4417/D4430企业生产设施，含其中填报为工业锅炉的35条记录）',
        '人工确认电力热力行业企业内填报为工业锅炉的设施归属')
