def build_summary(manifest, decisions, item_rows, exc_df, ctl_stats):
    from collections import Counter
    status_cnt = Counter(it['status'] for it in item_rows)
    target_cnt = Counter(d['decided_target'] for d in decisions.values())
    power_items = [it for it in item_rows if it['target'] == 'POWER']
    calc_items = [it for it in power_items if it['status'] == 'calculated']
    totals = {}
    for p in ALL_POLLUTANTS:
        sub = [it for it in calc_items if it['pollutant'] == p]
        totals[p] = dict(
            generation_t=round(sum(float(it['generation_t']) for it in sub), 4) if sub else 0.0,
            emission_t=round(sum(float(it['emission_t']) for it in sub), 4) if sub else 0.0,
            source_count=len(set(it['source_id'] for it in sub)))
    return dict(
        run_id=manifest['run_id'],
        target=manifest['target'],
        scale_percent=manifest['scale_percent'],
        input_variant=manifest['input_variant'],
        standard_pdf='inputs/T_CSES_144-2024.pdf',
        standard_reference='T/CSES 144-2024《城市大气污染源排放清单编制技术指南》：§5.2.1/§7.1源分类，§7.2.1.2/§7.2.2产排污系数法（公式2），公式3-6物料衡算，附录A表A.1、附录C表C.1-C.3、附录D表D.1',
        classification_rule=(
            'POWER=行业类别代码∈{4411,4412,4417,4430}(指南§7.1)；'
            'INDUSTRIAL_BOILER=工业锅炉且行业∈工业源范围(B06-12/C13-43/D45,指南§8.1/§8.3)；'
            '其余(电站锅炉位于非电力热力行业、4419垃圾焚烧、非工业行业工业锅炉)=OUT_OF_SCOPE'),
        control_rule=(
            '治理设施按统一社会信用代码归并到企业；处理工艺名称映射附录A表A.1，'
            '设施填报去除效率(0<η≤100)覆盖其主控污染物组，跨污染物协同效率取表A.1；'
            '多设施按串联组合1-∏(1-η)；基102低氮燃烧=是且无低氮脱硝设施时叠加NOx 22%；'
            'VOCs燃烧烟气η=0(指南§8.2.1.2(5))；投运率无运行时间数据，η直接采用填报/表A.1值'),
        inputs=dict(
            base102='inputs/基102-2002_原始结构脱敏输入.xlsx',
            base101_2001_shards=['inputs/基101-2001_原始结构脱敏输入_分片%02d-of04.xlsx' % i for i in range(1, 5)],
            base101_2002='inputs/基101-2002_原始结构脱敏输入.xlsx',
            source_identity_index='inputs/source_identity_index.json',
            standard_pdf='inputs/T_CSES_144-2024.pdf'),
        sources_processed=len(decisions),
